    value = {"class": max((r.get("class") for r in routes), key=lambda c: _rank(CLASS_ORDER, c)),
             "effort": max((r.get("effort") for r in routes), key=lambda e: _rank(EFFORT_ORDER, e))}
    for field in ("provider", "model", "settings"):
